package main

import "fmt"

func whereSum(lst []int) int {
	var total int
	for _, v := range lst {
		if v > 5 {
			total += v
		}
	}
	return total
}

func main() {
	lst := []int{4, 7, 2, 9, 12}
	fmt.Println("Sum:", whereSum(lst))
}

package main

import "fmt"

func greet(name string) string {
	return fmt.Sprintf("Hello, %s", name)
}

func square(number int) int {
	return number * number
}

func main() {
	fmt.Println(greet("friend"))
	fmt.Printf("Six squared is %d\n", square(6))
}
